DROP POLICY IF EXISTS buildpulse_edition_pdfs_service_update ON storage.objects; DROP POLICY IF EXISTS buildpulse_edition_pdfs_service_delete ON storage.objects;
CREATE OR REPLACE FUNCTION buildpulse_lock_sent_edition() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.status='sent' THEN IF NEW.subject IS DISTINCT FROM OLD.subject OR NEW.preheader IS DISTINCT FROM OLD.preheader OR NEW.body_html IS DISTINCT FROM OLD.body_html OR NEW.body_text IS DISTINCT FROM OLD.body_text OR NEW.slug IS DISTINCT FROM OLD.slug OR NEW.revision_number IS DISTINCT FROM OLD.revision_number OR NEW.pdf_path IS DISTINCT FROM OLD.pdf_path OR NEW.pdf_sha256 IS DISTINCT FROM OLD.pdf_sha256 OR NEW.pdf_revision IS DISTINCT FROM OLD.pdf_revision THEN RAISE EXCEPTION 'sent BuildPulse edition content and artifact are immutable'; END IF; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS trg_buildpulse_lock_sent_edition ON buildpulse_editions; CREATE TRIGGER trg_buildpulse_lock_sent_edition BEFORE UPDATE ON buildpulse_editions FOR EACH ROW EXECUTE FUNCTION buildpulse_lock_sent_edition();
